// Construit un prompt par offre : profil complet du candidat + offre
const p = $('Profil candidat').first().json;
const list = (a) => (Array.isArray(a) && a.length ? a.join(', ') : 'non précisé');

const profile = [
  `Nom : ${p.full_name || 'non précisé'}`,
  `Titre : ${p.headline || 'non précisé'}`,
  `Postes visés : ${list(p.target_roles)}`,
  `Compétences : ${list(p.skills)}`,
  `Années d'expérience : ${p.years_experience ?? 'non précisé'}`,
  `Localisations souhaitées : ${list(p.locations)}`,
  `Contrats souhaités : ${list(p.contract_types)}`,
  `Télétravail : ${p.remote_preference || 'indifférent'}`,
  `Salaire minimum : ${p.salary_min ? p.salary_min + ' € brut/an' : 'non précisé'}`,
  `Langues : ${list(p.languages)}`,
  `Préférences : ${p.preferences || 'aucune'}`,
  `CV :\n${(p.cv_text || 'CV non fourni').slice(0, 6000)}`,
].join('\n');

const SYSTEM = "Tu es un recruteur tech senior et un coach carrière exigeant mais bienveillant.\nTu évalues l'adéquation entre un candidat et une offre d'emploi, de façon honnête et argumentée.\n\nBarème du score (0-100) :\n- 85-100 : le profil coche presque tout (compétences, niveau, localisation/télétravail, contrat)\n- 70-84 : très bonne piste, quelques écarts comblables\n- 50-69 : piste possible mais écarts significatifs\n- 0-49 : peu pertinent (métier différent, niveau inadapté, contrat ou lieu incompatibles)\nPénalise fortement : niveau d'expérience très au-dessus du candidat, contrat ou localisation incompatibles avec ses préférences.\nN'invente jamais d'information absente de l'offre ou du profil.\n\nRéponds UNIQUEMENT avec un objet JSON valide, en français, de la forme :\n{\n  \"score\": 0,\n  \"verdict\": \"excellent | bon | moyen | faible\",\n  \"summary\": \"Résumé de l'offre en 2 phrases maximum\",\n  \"strengths\": [\"Pourquoi le profil correspond (3 max, phrases courtes)\"],\n  \"gaps\": [\"Écarts entre le profil et l'offre (3 max, phrases courtes)\"],\n  \"missing_skills\": [\"Compétences techniques demandées absentes du profil, noms courts (ex. Docker)\"],\n  \"key_skills\": [\"Compétences clés demandées par l'offre, noms courts (8 max)\"],\n  \"red_flags\": [\"Signaux d'alerte éventuels : exigences irréalistes, salaire flou, flou sur le poste... (peut être vide)\"],\n  \"seniority\": \"junior | confirmé | senior | non précisé\",\n  \"remote\": \"sur site | hybride | full remote | non précisé\",\n  \"estimated_salary\": \"Salaire de l'offre, ou fourchette estimée du marché français (ex. '38-45 k€ brut/an')\"\n}";

// (PostgreSQL renvoie { success: true } quand aucune offre n'est à analyser : on s'arrête là)
return $('Réserver les offres à analyser').all().filter((i) => i.json.id).map(({ json: j }) => ({
  json: {
    job_id: j.id,
    llm_body: {
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        {
          role: 'user',
          content: [
            '### PROFIL DU CANDIDAT', profile, '',
            `### OFFRE #${j.id}`,
            `Intitulé : ${j.title}`,
            `Entreprise : ${j.company || 'non précisée'}`,
            `Lieu : ${j.location || 'non précisé'}`,
            `Contrat : ${j.contract_type || 'non précisé'}`,
            `Salaire : ${j.salary || 'non précisé'}`,
            'Description :', (j.description || '').slice(0, 7000),
          ].join('\n'),
        },
      ],
    },
  },
}));

// Retrouve l'élément d'origine d'un item grâce au suivi des « paired items » de n8n
const origin = (node, i) => { try { return $(node).itemMatching(i)?.json; } catch (e) { return $(node).all()[i]?.json; } };
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};

// Valide et nettoie la réponse de l'IA (le modèle peut se tromper de format)
const VERDICTS = ['excellent', 'bon', 'moyen', 'faible'];
const strings = (a, max = 8) => Array.isArray(a)
  ? a.filter((x) => typeof x === 'string' && x.trim()).map((x) => x.trim().slice(0, 160)).slice(0, max)
  : [];
const text = (s, max = 400) => (typeof s === 'string' && s.trim() ? s.trim().slice(0, max) : null);

const results = $input.all().map((item, i) => {
  const job_id = origin('Préparer les prompts', i)?.job_id;
  try {
    const r = parseLLM(item.json);
    const score = Math.round(Number(r.score));
    if (!Number.isFinite(score)) throw new Error('Score manquant dans la réponse IA');
    const clamped = Math.max(0, Math.min(100, score));
    const verdict = VERDICTS.includes(String(r.verdict).toLowerCase())
      ? String(r.verdict).toLowerCase()
      : clamped >= 85 ? 'excellent' : clamped >= 70 ? 'bon' : clamped >= 50 ? 'moyen' : 'faible';
    return {
      job_id,
      score: clamped,
      verdict,
      summary: text(r.summary, 600),
      strengths: strings(r.strengths, 4),
      gaps: strings(r.gaps, 4),
      missing_skills: strings(r.missing_skills, 8).map((s) => s.slice(0, 40)),
      key_skills: strings(r.key_skills, 10).map((s) => s.slice(0, 40)),
      red_flags: strings(r.red_flags, 4),
      seniority: text(r.seniority, 40),
      remote: text(r.remote, 40),
      estimated_salary: text(r.estimated_salary, 80),
      error: null,
    };
  } catch (e) {
    return { job_id, error: String(e.message || e).slice(0, 500) };
  }
}).filter((r) => r.job_id);

return [{ json: { results } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const scoreEmoji = (s) => s >= 85 ? '🔥' : s >= 70 ? '✅' : s >= 50 ? '🟡' : '⚪';

// Garde les offres au-dessus du seuil d'alerte (ou l'offre importée à la main)
const threshold = $('Profil candidat').first().json.alert_threshold ?? 75;
const forced = $('Réserver les offres à analyser').first().json.forced === true;
const bullets = (arr) => (arr || []).map((x) => `• ${esc(x)}`).join('\n');

const out = [];
for (const { json: j } of $input.all()) {
  if (!j.id) continue;
  if (j.failed) {
    if (forced) out.push({ json: { job_id: j.id, url: j.url || 'https://francetravail.fr', text: `⚠️ Je n'ai pas réussi à analyser l'offre #${j.id} (${esc(j.error)}). Réessaie avec /offre_${j.id} plus tard.` } });
    continue;
  }
  if (!forced && (j.score < threshold || j.alerted_at)) continue;

  const lines = [
    `${scoreEmoji(j.score)} <b>${j.score}/100 · match ${esc(j.verdict)}</b>${forced ? '' : ' · nouvelle pépite !'}`,
    '',
    `<b>${esc(j.title)}</b>`,
    `🏢 ${esc(j.company || 'Entreprise non précisée')}`,
    `📍 ${esc(j.location || '—')}${j.contract_type ? ' · 📄 ' + esc(j.contract_type) : ''}${j.remote && j.remote !== 'non précisé' ? ' · 🏠 ' + esc(j.remote) : ''}`,
    `💶 ${esc(j.salary || (j.estimated_salary ? j.estimated_salary + ' (estimé)' : 'non précisé'))}`,
  ];
  if (j.summary) lines.push('', `📝 ${esc(j.summary)}`);
  if (j.strengths?.length) lines.push('', '<b>✅ Pourquoi ça matche</b>', bullets(j.strengths));
  if (j.gaps?.length) lines.push('', '<b>⚠️ Points d\'attention</b>', bullets(j.gaps));
  if (j.missing_skills?.length) lines.push('', `🧩 <b>À renforcer :</b> ${esc(j.missing_skills.join(', '))}`);
  if (j.red_flags?.length) lines.push('', '<b>🚩 Signaux d\'alerte</b>', bullets(j.red_flags));
  lines.push('', `<i>Offre #${j.id} · /offre_${j.id}</i>`);

  out.push({ json: { job_id: j.id, url: j.url || 'https://francetravail.fr', text: lines.join('\n') } });
}
return out;

